import os
import time

import requests

BASE = os.environ["NOMUS_BASE_URL"]      # ex.: https://<<SUA_EMPRESA>>.nomus.com.br/<<SUA_EMPRESA>>/rest
CHAVE = os.environ["NOMUS_CHAVE_REST"]   # <<SUA_CHAVE_INTEGRACAO_REST>> (Configuração Geral do ERP)
HEADERS = {"Authorization": f"Basic {CHAVE}", "Content-Type": "application/json"}
INTERVALO = 20  # segundos: limite publicado pela Nomus (1 requisição a cada 20 s)


def chamar(metodo, caminho, params=None, corpo=None, tentativas=5):
    """Faz a chamada e, em 429, espera o tempoAteLiberar informado pela Nomus."""
    for _ in range(tentativas):
        r = requests.request(metodo, f"{BASE}{caminho}", headers=HEADERS, params=params, json=corpo, timeout=60)
        if r.status_code == 429:
            try:
                espera = int(r.json().get("tempoAteLiberar", INTERVALO))
            except ValueError:
                espera = INTERVALO
            time.sleep(espera + 1)
            continue
        if r.status_code >= 400:
            raise RuntimeError(f"Nomus respondeu HTTP {r.status_code}: {r.text[:300]}")
        return r.json() if r.content else None
    raise RuntimeError("limite de requisições: tentativas esgotadas")


def listar(caminho, query=None):
    """Pagina de 50 em 50 (tamanho fixo) até vir uma página incompleta."""
    registros, pagina = [], 1
    while True:
        params = {"pagina": pagina}
        if query:
            params["query"] = query
        lote = chamar("GET", caminho, params) or []
        if isinstance(lote, dict):  # alguns exemplos oficiais devolvem objeto único
            lote = [lote]
        registros.extend(lote)
        if len(lote) < 50:
            break
        pagina += 1
        time.sleep(INTERVALO)
    return registros


if __name__ == "__main__":
    linhas = listar("/contasReceber", "dataVencimento>=2026-08-01T00:00:00;dataVencimento<=2026-08-31T23:59:59")
    print(len(linhas), "registros")

snippets.typescript:
const BASE = process.env.NOMUS_BASE_URL!;   // https://<<SUA_EMPRESA>>.nomus.com.br/<<SUA_EMPRESA>>/rest
const CHAVE = process.env.NOMUS_CHAVE_REST!; // <<SUA_CHAVE_INTEGRACAO_REST>>
const HEADERS = { Authorization: `Basic ${CHAVE}`, "Content-Type": "application/json" };
const espera = (s: number) => new Promise((r) => setTimeout(r, s * 1000));

async function chamar(caminho: string, params: Record<string, string>): Promise<any> {
  for (let t = 0; t < 5; t++) {
    const r = await fetch(`${BASE}${caminho}?${new URLSearchParams(params)}`, { headers: HEADERS });
    if (r.status === 429) {
      const corpo: any = await r.json().catch(() => ({}));
      await espera((corpo.tempoAteLiberar ?? 20) + 1);   // throttling da Nomus
      continue;
    }
    if (!r.ok) throw new Error(`Nomus respondeu HTTP ${r.status}: ${await r.text()}`);
    return r.json();
  }
  throw new Error("limite de requisições: tentativas esgotadas");
}

async function listar(caminho: string, query?: string) {
  const registros: any[] = [];
  for (let pagina = 1; ; pagina++) {
    const params: Record<string, string> = { pagina: String(pagina) };
    if (query) params.query = query;
    let lote = await chamar(caminho, params);
    if (!Array.isArray(lote)) lote = lote ? [lote] : [];
    registros.push(...lote);
    if (lote.length < 50) break;   // tamanho de página fixo em 50
    await espera(20);              // 1 requisição a cada 20 s
  }
  return registros;
}

listar("/contasReceber", "dataVencimento>=2026-08-01T00:00:00;dataVencimento<=2026-08-31T23:59:59").then((l) => console.log(`${l.length} registros`));

